using System.Collections.Generic;
using UnityEngine;

namespace Oathdeep.Core
{
    /// <summary>
    /// Plays states by name on the Animator generated by the Aseprite importer (one state per Aseprite tag).
    /// Missing states are ignored so art can arrive incrementally.
    /// </summary>
    public sealed class AnimDriver : MonoBehaviour
    {
        [SerializeField] Animator animator;
        [SerializeField] SpriteRenderer spriteRenderer;

        readonly Dictionary<string, int> hashes = new Dictionary<string, int>();
        string current;

        public SpriteRenderer Renderer => spriteRenderer;

        void Awake()
        {
            if (animator == null) animator = GetComponentInChildren<Animator>();
            if (spriteRenderer == null) spriteRenderer = GetComponentInChildren<SpriteRenderer>();
        }

        public void Setup(Animator a, SpriteRenderer r)
        {
            animator = a;
            spriteRenderer = r;
        }

        public void Play(string state, bool restart = false)
        {
            if (animator == null || animator.runtimeAnimatorController == null) return;
            if (!restart && current == state) return;
            if (!hashes.TryGetValue(state, out int hash)) hashes[state] = hash = Animator.StringToHash(state);
            if (!animator.HasState(0, hash)) return;
            animator.Play(hash, 0, 0f);
            current = state;
        }

        public void SetSpeed(float speed) { if (animator != null) animator.speed = speed; }

        public void Face(float x)
        {
            if (spriteRenderer != null && Mathf.Abs(x) > 0.01f) spriteRenderer.flipX = x < 0f;
        }
    }
}
